const params=new URLSearchParams(location.search),requested=params.get('species')||'mango',language=localStorage.getItem('tfruitllm-language')==='zh'?'zh':'en';
const root=document.querySelector('#genomeContent'),back=document.querySelector('#resourceBack');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const text={en:{back:'Research resources',catalog:'PUBLIC GENOME ASSEMBLIES',assemblies:'NCBI assemblies',gwhAssemblies:'direct GWH assemblies',updated:'Database records updated',switchSpecies:'Switch species',modelTitle:'Genome version used by TropicalfruitLLM v1.0',modelBody:'No single fixed genome assembly. The model was fine-tuned from literature, question-answer and multi-omics evidence; its weights are not built from or bound to one unified genome FASTA. For reproducible analysis, cite the exact assembly accession used.',otherTitle:'Confirmed records in other repositories',otherBody:'Only repositories with confirmed records for this species are shown. ENA and DDBJ mirror INSDC data and are not counted as additional genome versions.',gwhTitle:'Genome Warehouse direct submissions',gwhBody:'Independent assemblies deposited directly in NGDC Genome Warehouse.',ena:'ENA assemblies',ddbj:'DDBJ assemblies',public:'NCBI public assembly',gwhPublic:'GWH direct submission',accession:'Accession',name:'Assembly name',sample:'Cultivar / isolate',level:'Assembly level',date:'Release date',project:'BioProject',record:'Repository record',download:'Download genome',empty:'No public assembly is currently listed for this species.'},zh:{back:'返回研究资源',catalog:'公开基因组组装目录',assemblies:'个 NCBI 组装版本',gwhAssemblies:'个 GWH 独立提交组装',updated:'数据库记录更新于',switchSpecies:'切换物种',modelTitle:'TropicalfruitLLM v1.0 使用的基因组版本',modelBody:'未绑定单一固定基因组版本。模型基于文献、问答与多组学证据微调，模型权重并非由某一个统一的基因组 FASTA 组装构建。涉及可复现分析时，应明确引用实际使用的组装登录号。',otherTitle:'其他数据库中的已确认记录',otherBody:'仅展示已确认存在该物种记录的数据库；ENA 与 DDBJ 的 INSDC 镜像不重复计为新的基因组版本。',gwhTitle:'Genome Warehouse 独立提交组装',gwhBody:'直接提交至 NGDC Genome Warehouse、并非由 NCBI 整合而来的独立组装。',ena:'ENA 基因组组装',ddbj:'DDBJ 基因组组装',public:'NCBI 公开组装',gwhPublic:'GWH 独立提交',accession:'登录号',name:'组装名称',sample:'品种 / 样本',level:'组装层级',date:'发布日期',project:'BioProject',record:'数据库记录',download:'下载基因组',empty:'NCBI 当前未列出该物种的公开组装。'}}[language];
document.documentElement.lang=language==='zh'?'zh-CN':'en';back.textContent=text.back;
const sampleLabel=assembly=>[assembly.cultivar,assembly.isolate&&`isolate=${assembly.isolate}`].filter(Boolean).join(' · ')||'—';
Promise.all([fetch('data/genomes.json').then(response=>response.json()),fetch('data/external-genomes.json').then(response=>response.json())]).then(([data,externalData])=>{
  const species=data.species.find(item=>item.key===requested)||data.species[0],assemblies=species.assemblies||[];
  const externalSpecies=externalData.species.find(item=>item.key===species.key),gwhRecords=externalSpecies?.records||[];
  document.title=`${species.commonName} Genome Assemblies | TropicalfruitLLM v1.0`;
  const speciesOptions=data.species.map(item=>`<option value="${esc(item.key)}"${item.key===species.key?' selected':''}>${esc(item.commonName)} · ${esc(item.scientificName)} (${item.assemblies.length})</option>`).join('');
  const query=encodeURIComponent(species.scientificName),taxid=encodeURIComponent(species.taxid||species.scientificName);
  const hasInsdcAssembly=assemblies.some(assembly=>/^GCA_/i.test(assembly.accession));
  const repositories=hasInsdcAssembly?[
    [text.ena,`https://www.ebi.ac.uk/ena/browser/advanced-search?query=tax_tree(${taxid})&result=assembly`,'INSDC'],
    [text.ddbj,`https://ddbj.nig.ac.jp/search/entry?database=assembly&query=${query}`,'INSDC']
  ]:[];
  const externalSection=repositories.length?`<section class="external-genomes"><div><span>EXTERNAL REPOSITORIES</span><h2>${text.otherTitle}</h2><p>${text.otherBody}</p></div><div class="repository-links">${repositories.map(([label,url,note])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(label)}</strong><small>${esc(note)}</small></a>`).join('')}</div></section>`:'';
  const gwhSection=gwhRecords.length?`<section class="assembly-section external-assembly-section"><header class="assembly-section-heading"><h2>${text.gwhTitle}</h2><p>${text.gwhBody}</p></header><div class="assembly-list">${gwhRecords.map(record=>`<article class="assembly-card external-card"><header><span>${text.gwhPublic}</span><strong>${esc(record.accession)}</strong></header><dl><div><dt>${text.name}</dt><dd>${esc(record.assemblyName||'—')}</dd></div><div><dt>${text.sample}</dt><dd>${esc(record.cultivar||'—')}</dd></div><div><dt>${text.level}</dt><dd>${esc(record.level||'—')}</dd></div><div><dt>${text.date}</dt><dd>${esc(record.releaseDate||'—')}</dd></div></dl><footer><a href="${esc(record.recordUrl)}" target="_blank" rel="noopener noreferrer">${text.record}</a>${record.downloadUrl?`<a class="primary" href="${esc(record.downloadUrl)}" target="_blank" rel="noopener noreferrer">${text.download}</a>`:''}</footer></article>`).join('')}</div></section>`:'';
  root.innerHTML=`<section class="genome-heading"><div class="genome-heading-row"><div><p class="eyebrow">${text.catalog}</p><h1>${esc(species.commonName)}</h1><p class="scientific-name">${esc(species.scientificName)}</p></div><label class="genome-species-switch"><span>${text.switchSpecies}</span><select id="genomeSpeciesSelect">${speciesOptions}</select></label></div><div class="genome-summary"><strong>${assemblies.length}</strong><span>${text.assemblies}</span>${gwhRecords.length?`<strong>${gwhRecords.length}</strong><span>${text.gwhAssemblies}</span>`:''}<small>${text.updated} ${esc(data.updated)}</small></div></section><section class="model-genome-note"><span>MODEL GENOME STATUS</span><div><h2>${text.modelTitle}</h2><p>${text.modelBody}</p></div></section>${externalSection}${gwhSection}<section class="assembly-section"><div class="assembly-list">${assemblies.length?assemblies.map(assembly=>`<article class="assembly-card"><header><span>${text.public}</span><strong>${esc(assembly.accession)}</strong></header><dl><div><dt>${text.name}</dt><dd>${esc(assembly.assemblyName||'—')}</dd></div><div><dt>${text.sample}</dt><dd>${esc(sampleLabel(assembly))}</dd></div><div><dt>${text.level}</dt><dd>${esc(assembly.level||'—')}</dd></div><div><dt>${text.date}</dt><dd>${esc(assembly.releaseDate||'—')}</dd></div><div><dt>${text.project}</dt><dd>${esc(assembly.bioproject||'—')}</dd></div></dl><footer><a href="${esc(assembly.ncbiUrl)}" target="_blank" rel="noopener noreferrer">${text.record}</a><a class="primary" href="${esc(assembly.downloadUrl||assembly.ncbiUrl)}" target="_blank" rel="noopener noreferrer">${text.download}</a></footer></article>`).join(''):`<p class="empty-assemblies">${text.empty}</p>`}</div></section>`;
  document.querySelector('#genomeSpeciesSelect').addEventListener('change',event=>{location.href=`genomes.html?species=${encodeURIComponent(event.target.value)}`});
}).catch(()=>{root.innerHTML='<p class="loading">Genome assembly data are temporarily unavailable.</p>'});
